// ===== BP — Bounce Handler : Extract Failed Recipients =====
// Input: raw MAILER-DAEMON / postmaster notices from Gmail.
// Output: one item per unique HARD-bounced address.
// A lead is only burned when the failure is permanent AND unambiguous — a delay notice,
// a full mailbox or a reason we cannot read all leave the record untouched.

const OUR_DOMAINS = ["businesspartnerksa.com","businesspartner.sa","googlemail.com","google.com","mailer-daemon.com"];
const OUR_ADDRESSES = ["business@businesspartnerksa.com","dr.baher.magnas@gmail.com","mailer-daemon@googlemail.com","postmaster@googlemail.com"];

const RE_ANY_EMAIL = /[a-z0-9._%+'-]+@[a-z0-9][a-z0-9.-]*\.[a-z]{2,}/gi;

// Not a failure at all — the server is still trying.
const NOT_A_FAILURE = ["(delay)","delayed","warning: message","delivery delayed","still trying","will retry"];

// Permanent whatever the numeric code says: the address itself is wrong.
const HARD_PHRASES = [
  "does not exist","doesn't exist","user unknown","unknown user","no such user",
  "address not found","recipient not found","mailbox not found","user does not exist",
  "invalid recipient","no mailbox","domain not found","unrouteable address",
  "recipient address rejected","account that you tried to reach","nxdomain",
];

// Temporary in practice, even though the code is in the 5xx range.
const SOFT_PHRASES = ["mailbox is full","mailbox full","over quota","quota exceeded","insufficient system storage","try again later","temporarily","greylist"];

function textOf(j) {
  const parts = [j.text, j.textAsHtml, j.html, j.snippet, j.subject];
  if (j.payload) { try { parts.push(JSON.stringify(j.payload)); } catch (e) {} }
  return parts.filter(Boolean).join("\n");
}

function failedRecipient(body) {
  const ordered = [
    /Final-Recipient:\s*(?:rfc822;)?\s*<?([a-z0-9._%+'-]+@[a-z0-9][a-z0-9.-]*\.[a-z]{2,})>?/i,
    /Original-Recipient:\s*(?:rfc822;)?\s*<?([a-z0-9._%+'-]+@[a-z0-9][a-z0-9.-]*\.[a-z]{2,})>?/i,
    /(?:wasn't|was not|couldn't be|could not be) delivered to:?\s*<?([a-z0-9._%+'-]+@[a-z0-9][a-z0-9.-]*\.[a-z]{2,})>?/i,
    /to\s+<?([a-z0-9._%+'-]+@[a-z0-9][a-z0-9.-]*\.[a-z]{2,})>?\s+(?:because|failed|has been)/i,
  ];
  for (const re of ordered) {
    const m = body.match(re);
    if (m) return m[1].toLowerCase();
  }
  const all = body.match(RE_ANY_EMAIL) || [];
  for (const raw of all) {
    const e = raw.toLowerCase();
    if (OUR_ADDRESSES.includes(e)) continue;
    if (OUR_DOMAINS.includes(e.split("@")[1])) continue;
    return e;
  }
  return "";
}

function severity(body) {
  const low = body.toLowerCase();
  if (SOFT_PHRASES.some(p => low.includes(p))) return "soft";

  const status = body.match(/Status:\s*([245])\.(\d+)\.(\d+)/i);
  if (status) {
    if (status[1] !== "5") return "soft";
    // 5.2.2 is a full mailbox — the address is fine, the inbox is not.
    if (status[2] === "2" && status[3] === "2") return "soft";
    return "hard";
  }
  if (/\b552\b/.test(body)) return "soft";
  if (HARD_PHRASES.some(p => low.includes(p))) return "hard";
  if (/\b5\d\d[\s-]/.test(body)) return "hard";
  if (/\b4\d\d[\s-]/.test(body)) return "soft";
  return "unknown";
}

function reason(body) {
  const diag = body.match(/Diagnostic-Code:\s*([^\n\r]{0,180})/i);
  if (diag) return diag[1].trim();
  const line = body.match(/((?:5|4)\d\d[- ][^\n\r]{0,160})/);
  if (line) return line[1].trim();
  return "";
}

const seen = new Map();
let soft = 0, delayed = 0, unclear = 0, unparsed = 0;

for (const item of $input.all()) {
  const j = item.json;
  const body = textOf(j);
  if (!body) { unparsed++; continue; }

  const subject = String(j.subject || "").toLowerCase();
  if (NOT_A_FAILURE.some(p => subject.includes(p))) { delayed++; continue; }

  const email = failedRecipient(body);
  if (!email) { unparsed++; continue; }

  const sev = severity(body);
  if (sev === "soft") { soft++; continue; }
  // Never suppress on a reason we could not read.
  if (sev !== "hard") { unclear++; continue; }

  if (seen.has(email)) continue;
  seen.set(email, {
    _email: email,
    _severity: sev,
    _detail: (reason(body) || "Hard bounce reported by the receiving server").slice(0, 190),
    _messageId: j.id || "",
    _subject: j.subject || "",
  });
}

console.log("notices read:", $input.all().length, "| hard:", seen.size, "| soft:", soft, "| delays:", delayed, "| unclear:", unclear, "| unparsed:", unparsed);
return [...seen.values()].map(v => ({ json: v }));
